-- SOURCE CANDIDATE: explicit original-event cancellation, not a semantic approval.
-- No old grants, roles, tables, quotas, clocks, numerical scores or prompt defaults change.
BEGIN ISOLATION LEVEL READ COMMITTED;
SET LOCAL statement_timeout='30s';SET LOCAL lock_timeout='2s';
SELECT pg_advisory_xact_lock(64221022);
DO $cancellation$
DECLARE targets oid[]:=ARRAY[to_regprocedure('public.vnext_command_v1(text,text,jsonb)')::oid,to_regprocedure('public.vnext_provider_command_v1(text,text,jsonb)')::oid];additions oid[]:=ARRAY[]::oid[];before_namespace jsonb;after_namespace jsonb;target oid;original text;changed text;definition text;metadata jsonb;spec record;constraint_metadata jsonb;constraint_definition text;
 catalog_sql constant text:=$catalog$
 SELECT jsonb_build_object(
  'namespace',(SELECT to_jsonb(n) FROM pg_namespace n WHERE n.oid='public'::regnamespace),
  'routines',(SELECT coalesce(jsonb_agg(CASE WHEN p.oid=ANY($1) THEN to_jsonb(p)-'prosrc' ELSE to_jsonb(p) END ORDER BY p.oid),'[]'::jsonb) FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND NOT(p.oid=ANY($2))),
  'relations',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.oid),'[]'::jsonb) FROM pg_class c WHERE c.relnamespace='public'::regnamespace),
  'columns',(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.attrelid,a.attnum),'[]'::jsonb) FROM pg_attribute a WHERE a.attrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'types',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.oid),'[]'::jsonb) FROM pg_type t WHERE t.typnamespace='public'::regnamespace),
  'constraints',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.oid),'[]'::jsonb) FROM pg_constraint c WHERE c.connamespace='public'::regnamespace AND NOT(c.conrelid='public.vnext_provider_bindings_v1'::regclass AND c.conname='vnext_provider_bindings_v1_prompt_version_check')),
  'defaults',(SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.oid),'[]'::jsonb) FROM pg_attrdef d WHERE d.adrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'indexes',(SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.indexrelid),'[]'::jsonb) FROM pg_index i WHERE i.indrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'policies',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.oid),'[]'::jsonb) FROM pg_policy p WHERE p.polrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'triggers',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.oid),'[]'::jsonb) FROM pg_trigger t WHERE t.tgrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'rules',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.oid),'[]'::jsonb) FROM pg_rewrite r WHERE r.ev_class IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'operators',(SELECT coalesce(jsonb_agg(to_jsonb(o) ORDER BY o.oid),'[]'::jsonb) FROM pg_operator o WHERE o.oprnamespace='public'::regnamespace),
  'collations',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.oid),'[]'::jsonb) FROM pg_collation c WHERE c.collnamespace='public'::regnamespace),
  'defaultAcls',(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.oid),'[]'::jsonb) FROM pg_default_acl a WHERE a.defaclnamespace IN(0,'public'::regnamespace)),
  'roles',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.rolname) FROM pg_roles r),
  'memberships',(SELECT coalesce(jsonb_agg(to_jsonb(m) ORDER BY m.roleid,m.member),'[]'::jsonb) FROM pg_auth_members m))
 $catalog$;
BEGIN
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' OR array_position(targets,NULL) IS NOT NULL THEN RAISE EXCEPTION 'vnext_cancellation_prerequisites_missing';END IF;
 IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='stockinsider_vnext_owner' AND NOT rolcanlogin AND NOT rolsuper AND NOT rolcreatedb AND NOT rolcreaterole AND NOT rolreplication AND NOT rolbypassrls AND rolconfig IS NULL) OR EXISTS(SELECT FROM pg_auth_members WHERE member='stockinsider_vnext_owner'::regrole OR roleid='stockinsider_vnext_owner'::regrole) OR EXISTS(SELECT FROM pg_db_role_setting WHERE setrole='stockinsider_vnext_owner'::regrole AND setconfig IS NOT NULL) THEN RAISE EXCEPTION 'vnext_cancellation_owner_profile_changed';END IF;
 IF to_regprocedure('public.vnext_cancellation_original_v1(jsonb,jsonb,text,timestamp with time zone)') IS NOT NULL THEN RAISE EXCEPTION 'vnext_cancellation_first_install_required';END IF;
 IF to_regprocedure('public.vnext_cancellation_context_current_v1(uuid)') IS NOT NULL THEN RAISE EXCEPTION 'vnext_cancellation_first_install_required';END IF;
 IF to_regprocedure('public.vnext_catalyst_cancellation_current_v1(uuid,text)') IS NOT NULL THEN RAISE EXCEPTION 'vnext_cancellation_first_install_required';END IF;
 FOR spec IN SELECT * FROM(VALUES ('public.vnext_input_sources_current_v1(jsonb,text)','2e6a155ce7148f2ab550c414297bae42519339e9a4b7bad2ab658ce9a4ab398a'),('public.vnext_source_evidence_current_v1(jsonb,text)','712c701f18809a44fb788453e5e12a9d98b93f28ee3573973606d94bb739f0e8')) pin(signature,sha) LOOP
  IF NOT EXISTS(SELECT FROM pg_proc p WHERE p.oid=to_regprocedure(spec.signature) AND pg_get_userbyid(p.proowner)='stockinsider_vnext_owner' AND p.prosecdef AND encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')=spec.sha) THEN RAISE EXCEPTION 'vnext_cancellation_dependency_changed';END IF;
 END LOOP;
 SELECT pg_get_constraintdef(oid),to_jsonb(c)-'oid'-'conbin' INTO constraint_definition,constraint_metadata FROM pg_constraint c WHERE conrelid='public.vnext_provider_bindings_v1'::regclass AND conname='vnext_provider_bindings_v1_prompt_version_check';
 IF constraint_definition IS DISTINCT FROM 'CHECK ((prompt_version = ANY (ARRAY[''vnext-research-worker-v1''::text, ''vnext-research-worker-v2''::text, ''vnext-research-worker-v3''::text])))' OR obj_description((SELECT oid FROM pg_constraint WHERE conrelid='public.vnext_provider_bindings_v1'::regclass AND conname='vnext_provider_bindings_v1_prompt_version_check'),'pg_constraint') IS NOT NULL THEN RAISE EXCEPTION 'vnext_cancellation_prompt_predecessor_changed';END IF;
 EXECUTE catalog_sql INTO before_namespace USING targets,additions;
 EXECUTE $create_vnext_cancellation_original_v1$CREATE FUNCTION public.vnext_cancellation_original_v1(item jsonb,locator jsonb,p_symbol text,cutoff timestamptz) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET statement_timeout='30s' SET lock_timeout='2s' AS $function$DECLARE statement text; receipt public.vnext_extractions_v1; start_cp integer; end_cp integer;
BEGIN
 IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR jsonb_typeof(locator) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(locator))<>6 OR NOT(locator ?& ARRAY['evidenceId','contentHash','field','startCp','endCp','quote']) OR EXISTS(SELECT FROM unnest(ARRAY['evidenceId','contentHash','field','quote']) locator_field WHERE jsonb_typeof(locator->locator_field) IS DISTINCT FROM 'string') OR item->>'id' IS DISTINCT FROM locator->>'evidenceId' OR item->>'contentHash' IS DISTINCT FROM locator->>'contentHash' OR locator->>'field' IS DISTINCT FROM 'statement'
  OR item->>'key' IS DISTINCT FROM 'reported_event' OR item->>'kind' IS DISTINCT FROM 'assumption' OR item->>'sourceTier' IS DISTINCT FROM 'public' OR item->'value'->>'scope' IS DISTINCT FROM 'official_original' OR item->'value'->>'originSource' IS DISTINCT FROM 'official' OR item->'value'->>'claimStatus' IS DISTINCT FROM 'reported' OR item->'value'->>'originalContentHash' IS DISTINCT FROM item->>'contentHash' OR coalesce(item->'value'->>'eventBasis','') NOT IN('original_event','source_publication')
  OR jsonb_typeof(locator->'quote') IS DISTINCT FROM 'string' OR jsonb_typeof(locator->'startCp') IS DISTINCT FROM 'number' OR jsonb_typeof(locator->'endCp') IS DISTINCT FROM 'number' OR coalesce(locator->>'startCp','') !~ '^[0-9]+$' OR coalesce(locator->>'endCp','') !~ '^[0-9]+$' OR coalesce(item->>'contentHash','') !~ '^[a-f0-9]{64}$'
  OR NOT isfinite(cutoff) OR (item->>'availableAt')::timestamptz>cutoff OR (item->'value'->>'publishedAt')::timestamptz>(item->>'availableAt')::timestamptz OR public.vnext_source_evidence_current_v1(item,p_symbol) IS DISTINCT FROM true THEN RETURN false;END IF;
 SELECT * INTO receipt FROM public.vnext_extractions_v1 WHERE content_hash=item->>'contentHash' AND source='official' AND scope='official_original' AND state='completed' AND extraction->'evidence'=item;
 statement:=receipt.original->>'body';
 IF receipt.content_hash IS NULL OR NOT(receipt.original->'symbols' ? p_symbol) OR statement IS DISTINCT FROM item->'value'->>'statement' OR receipt.original->>'publishedAt' IS DISTINCT FROM item->'value'->>'publishedAt' OR receipt.original->>'availableAt' IS DISTINCT FROM item->>'availableAt' OR (locator->>'startCp')::numeric<0 OR (locator->>'endCp')::numeric>char_length(statement) OR (locator->>'startCp')::numeric>=(locator->>'endCp')::numeric OR char_length(locator->>'quote') NOT BETWEEN 12 AND 1024 THEN RETURN false;END IF;
 start_cp:=(locator->>'startCp')::integer;end_cp:=(locator->>'endCp')::integer;
 RETURN substring(statement FROM start_cp+1 FOR end_cp-start_cp) IS NOT DISTINCT FROM locator->>'quote';
END;
$function$;$create_vnext_cancellation_original_v1$;
 ALTER FUNCTION public.vnext_cancellation_original_v1(jsonb,jsonb,text,timestamp with time zone) OWNER TO stockinsider_vnext_owner;
 REVOKE ALL ON FUNCTION public.vnext_cancellation_original_v1(jsonb,jsonb,text,timestamp with time zone) FROM PUBLIC,anon,authenticated,service_role;
 EXECUTE $create_vnext_cancellation_context_current_v1$CREATE FUNCTION public.vnext_cancellation_context_current_v1(p_job uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET statement_timeout='30s' SET lock_timeout='2s' AS $function$DECLARE job public.vnext_jobs_v1; frozen jsonb; pub public.vnext_publications_v1; prior_job public.vnext_jobs_v1; prior_input jsonb; claims jsonb; originals jsonb; claim jsonb; e jsonb; checked jsonb; a public.vnext_provider_invocations_v1; r public.vnext_provider_invocations_v1; result jsonb;
BEGIN
 SELECT * INTO job FROM public.vnext_jobs_v1 WHERE job_id=p_job;
 SELECT evidence INTO frozen FROM public.vnext_preparations_v1 WHERE job_id=p_job AND input_hash=job.input_hash;
 IF job.job_id IS NULL OR job.state NOT IN('running','authored','reviewing','published') OR frozen IS NULL OR NOT EXISTS(SELECT FROM public.vnext_members_v1 m WHERE m.symbol=job.symbol AND m.state<>'exited' AND NOT m.contraindication AND m.input_hash=job.input_hash) OR public.vnext_input_sources_current_v1(frozen,job.symbol) IS DISTINCT FROM true THEN RETURN NULL;END IF;
 result:=jsonb_build_object('schemaVersion','vnext-cancellation-context-v1','symbol',job.symbol,'inputHash',job.input_hash,'baseline',NULL);
 SELECT * INTO pub FROM public.vnext_publications_v1 WHERE symbol=job.symbol AND job_id<>p_job ORDER BY published_at DESC,revision_id DESC LIMIT 1;
 IF pub.revision_id IS NULL THEN RETURN result;END IF;
 SELECT * INTO prior_job FROM public.vnext_jobs_v1 WHERE job_id=pub.job_id;
 SELECT evidence INTO prior_input FROM public.vnext_preparations_v1 WHERE job_id=pub.job_id AND input_hash=pub.input_hash;
 IF prior_job.state IS DISTINCT FROM 'published' OR prior_job.symbol IS DISTINCT FROM job.symbol OR prior_job.input_hash IS DISTINCT FROM pub.input_hash OR prior_job.author_result IS DISTINCT FROM pub.content OR prior_input IS NULL OR prior_job.reviewer_result->>'approved' IS DISTINCT FROM 'true' OR prior_job.reviewer_result->>'authorOutputHash' IS DISTINCT FROM pub.content->>'outputHash'
  OR pub.published_at>(frozen->>'cutoff')::timestamptz OR (prior_input->>'cutoff')::timestamptz>pub.published_at
  OR pub.content->>'outputHash' IS DISTINCT FROM encode(sha256(convert_to(public.vnext_catalog_canonical_v1(pub.content-'outputHash'),'UTF8')),'hex') THEN RETURN NULL;END IF;
 SELECT coalesce(jsonb_agg(c ORDER BY c->>'id'),'[]'::jsonb) INTO claims FROM jsonb_array_elements(pub.content->'claims') c WHERE c ? 'semantic';
 IF jsonb_array_length(claims)>4 THEN RETURN NULL;END IF;
 SELECT coalesce(jsonb_agg(original_row ORDER BY original_row->>'id'),'[]'::jsonb) INTO originals FROM jsonb_array_elements(prior_input->'evidence') original_row WHERE EXISTS(SELECT FROM jsonb_array_elements(claims) c WHERE c->'semantic'->>'evidenceId'=original_row->>'id');
 IF jsonb_array_length(originals)>4 THEN RETURN NULL;END IF;
 IF jsonb_array_length(claims)>0 THEN
  SELECT * INTO a FROM public.vnext_provider_invocations_v1 WHERE job_id=pub.job_id AND task='author';
  SELECT * INTO r FROM public.vnext_provider_invocations_v1 WHERE job_id=pub.job_id AND task='reviewer';
  IF a.state IS DISTINCT FROM 'completed' OR r.state IS DISTINCT FROM 'completed' OR a.prompt_version NOT IN('vnext-research-worker-v3','vnext-research-worker-v4') OR r.prompt_version IS DISTINCT FROM a.prompt_version OR a.normalized_output IS DISTINCT FROM pub.content OR r.normalized_output IS DISTINCT FROM prior_job.reviewer_result
   OR a.principal IS DISTINCT FROM prior_job.author_principal OR r.principal IS DISTINCT FROM prior_job.reviewer_principal OR a.execution_id IS DISTINCT FROM prior_job.execution_id OR r.execution_id IS DISTINCT FROM prior_job.reviewer_execution OR a.principal=r.principal OR a.execution_id=r.execution_id OR a.invocation_id=r.invocation_id OR a.provider_response_id=r.provider_response_id OR a.provider_response_id IS NULL OR r.provider_response_id IS NULL
   OR a.request_hash IS DISTINCT FROM encode(sha256(convert_to(public.vnext_catalog_canonical_v1(a.frozen_request),'UTF8')),'hex') OR r.request_hash IS DISTINCT FROM encode(sha256(convert_to(public.vnext_catalog_canonical_v1(r.frozen_request),'UTF8')),'hex')
   OR a.provider IS DISTINCT FROM 'openai-responses' OR r.provider IS DISTINCT FROM 'openai-responses' OR coalesce(a.provider_response_id,'') !~ '^resp_[A-Za-z0-9_-]{1,160}$' OR coalesce(r.provider_response_id,'') !~ '^resp_[A-Za-z0-9_-]{1,160}$'
   OR a.frozen_request->>'model' IS DISTINCT FROM a.model OR r.frozen_request->>'model' IS DISTINCT FROM r.model
   OR encode(sha256(convert_to(a.frozen_request->>'instructions','UTF8')),'hex') IS DISTINCT FROM (CASE a.prompt_version WHEN 'vnext-research-worker-v3' THEN 'e9fd13b01b3d961cd612f1ef44136f07b7538ebcaae6142f2cedf21d96877803' ELSE '52d58cf0cf9682d8d87a601392589b642009ab8423a38c3acd1aaaff6719f5a5' END) OR encode(sha256(convert_to(r.frozen_request->>'instructions','UTF8')),'hex') IS DISTINCT FROM (CASE r.prompt_version WHEN 'vnext-research-worker-v3' THEN '9c5d0ccd2ef984d9924bf92eb59a70a3ba1bccdefb3d1086b783570d67f96f69' ELSE '6492f9a20300b9e01e62dc17b184aebfadbd916785c40cc2062dea9c8e02895d' END)
   OR a.input_hash IS DISTINCT FROM pub.input_hash OR r.input_hash IS DISTINCT FROM pub.input_hash OR (a.frozen_request->>'input')::jsonb->'evidence' IS DISTINCT FROM jsonb_build_object('cutoff',prior_input->'cutoff','evidence',prior_input->'evidence') OR (r.frozen_request->>'input')::jsonb->'evidence' IS DISTINCT FROM (a.frozen_request->>'input')::jsonb->'evidence'
   OR (r.frozen_request->>'input')::jsonb->'authorArtifact' IS DISTINCT FROM pub.content OR a.settled_at IS NULL OR r.settled_at IS NULL OR a.settled_at<a.started_at OR r.settled_at<r.started_at OR a.settled_at>a.deadline_at OR r.settled_at>r.deadline_at OR prior_job.sources_read_at IS NULL OR prior_job.sources_read_at<a.settled_at OR prior_job.sources_read_at>r.started_at OR pub.published_at<r.settled_at THEN RETURN NULL;END IF;
  FOR claim IN SELECT value FROM jsonb_array_elements(claims) LOOP
   IF claim->>'kind' IS DISTINCT FROM 'assumption' OR claim ? 'numeric' OR claim->'semantic'->>'schemaVersion' IS DISTINCT FROM 'vnext-catalyst-annotation-v1' OR claim->'semantic'->>'symbol' IS DISTINCT FROM job.symbol OR coalesce(claim->'semantic'->>'criterion','') NOT IN('catalyst_dated','catalyst_verified','catalyst_mechanism_documented','catalyst_falsifier_defined') OR coalesce(claim->'semantic'->>'outcome','') NOT IN('met','not_met','unknown') THEN RETURN NULL;END IF;
   SELECT value INTO e FROM jsonb_array_elements(originals) WHERE value->>'id'=claim->'semantic'->>'evidenceId';
   IF e IS NULL OR NOT EXISTS(SELECT FROM jsonb_array_elements(frozen->'evidence') current_e WHERE current_e=e) OR public.vnext_cancellation_original_v1(e,claim->'semantic'-'schemaVersion'-'criterion'-'outcome'-'symbol'-'catalystAt'-'catalystIdentity',job.symbol,(prior_input->>'cutoff')::timestamptz) IS DISTINCT FROM true THEN RETURN NULL;END IF;
   IF (SELECT count(*) FROM jsonb_array_elements(prior_job.reviewer_result->'claimChecks') c WHERE c->>'claimId'=claim->>'id')<>1 THEN RETURN NULL;END IF;
   SELECT value INTO checked FROM jsonb_array_elements(prior_job.reviewer_result->'claimChecks') WHERE value->>'claimId'=claim->>'id';
   IF checked->>'verdict' IS DISTINCT FROM 'supported' OR checked->'semanticAssessment'->'annotation' IS DISTINCT FROM claim->'semantic' OR coalesce(checked->'semanticAssessment'->>'assessment','') NOT IN('supported_report','supported_inference') OR claim->'semantic'->>'criterion' IN('catalyst_dated','catalyst_verified') AND checked->'semanticAssessment'->>'assessment' IS DISTINCT FROM 'supported_report' OR NOT EXISTS(SELECT FROM jsonb_array_elements(checked->'sources') s WHERE s->>'id'=e->>'id' AND s->>'contentHash'=e->>'contentHash') THEN RETURN NULL;END IF;
  END LOOP;
 END IF;
 result:=result||jsonb_build_object('baseline',jsonb_build_object('revisionId',pub.revision_id,'inputHash',pub.input_hash,'outputHash',pub.content->>'outputHash','publishedAt',to_jsonb(pub.published_at),'cutoff',prior_input->'cutoff','claims',claims,'evidence',originals));
 IF public.vnext_provider_envelope_v1(result) IS DISTINCT FROM true THEN RETURN NULL;END IF;
 RETURN result;
END;
$function$;$create_vnext_cancellation_context_current_v1$;
 ALTER FUNCTION public.vnext_cancellation_context_current_v1(uuid) OWNER TO stockinsider_vnext_owner;
 REVOKE ALL ON FUNCTION public.vnext_cancellation_context_current_v1(uuid) FROM PUBLIC,anon,authenticated,service_role;
 EXECUTE $create_vnext_catalyst_cancellation_current_v1$CREATE FUNCTION public.vnext_catalyst_cancellation_current_v1(p_job uuid,p_input_hash text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET statement_timeout='30s' SET lock_timeout='2s' AS $function$DECLARE job public.vnext_jobs_v1; frozen jsonb; context jsonb; a public.vnext_provider_invocations_v1; r public.vnext_provider_invocations_v1; author_input jsonb; reviewer_input jsonb; claim jsonb; annotation jsonb; assessment jsonb; checked jsonb; planned jsonb; cancelled jsonb; baseline_claim jsonb; catalyst_day date; proof jsonb; identity_text text; original_text text;
BEGIN
 IF p_job IS NULL OR coalesce(p_input_hash,'') !~ '^[a-f0-9]{64}$' THEN RETURN NULL;END IF;
 SELECT * INTO job FROM public.vnext_jobs_v1 WHERE job_id=p_job AND input_hash=p_input_hash;
 IF job.job_id IS NULL OR job.state NOT IN('reviewing','published') OR job.reviewer_result->>'approved' IS DISTINCT FROM 'true' OR job.reviewer_result->>'authorOutputHash' IS DISTINCT FROM job.author_result->>'outputHash' OR job.author_result->>'inputHash' IS DISTINCT FROM p_input_hash OR job.author_result->>'outputHash' IS DISTINCT FROM encode(sha256(convert_to(public.vnext_catalog_canonical_v1(job.author_result-'outputHash'),'UTF8')),'hex') THEN RETURN NULL;END IF;
 SELECT evidence INTO frozen FROM public.vnext_preparations_v1 WHERE job_id=p_job AND input_hash=p_input_hash;
 context:=public.vnext_cancellation_context_current_v1(p_job);
 IF frozen IS NULL OR context IS NULL OR clock_timestamp()>job.deadline_at AND job.state<>'published' OR job.sources_read_at IS NULL OR job.author_principal IS NULL OR job.reviewer_principal IS NULL OR job.author_principal=job.reviewer_principal OR job.execution_id IS NULL OR job.reviewer_execution IS NULL OR job.execution_id=job.reviewer_execution THEN RETURN NULL;END IF;
 SELECT * INTO a FROM public.vnext_provider_invocations_v1 WHERE job_id=p_job AND task='author';
 SELECT * INTO r FROM public.vnext_provider_invocations_v1 WHERE job_id=p_job AND task='reviewer';
 IF a.state IS DISTINCT FROM 'completed' OR r.state IS DISTINCT FROM 'completed' OR a.prompt_version IS DISTINCT FROM 'vnext-research-worker-v4' OR r.prompt_version IS DISTINCT FROM 'vnext-research-worker-v4' OR a.provider IS DISTINCT FROM 'openai-responses' OR r.provider IS DISTINCT FROM 'openai-responses' OR coalesce(a.provider_response_id,'') !~ '^resp_[A-Za-z0-9_-]{1,160}$' OR coalesce(r.provider_response_id,'') !~ '^resp_[A-Za-z0-9_-]{1,160}$' OR a.provider_response_id=r.provider_response_id OR a.invocation_id=r.invocation_id
  OR a.principal IS DISTINCT FROM job.author_principal OR r.principal IS DISTINCT FROM job.reviewer_principal OR a.execution_id IS DISTINCT FROM job.execution_id OR r.execution_id IS DISTINCT FROM job.reviewer_execution OR a.input_hash IS DISTINCT FROM p_input_hash OR r.input_hash IS DISTINCT FROM p_input_hash OR a.normalized_output IS DISTINCT FROM job.author_result OR r.normalized_output IS DISTINCT FROM job.reviewer_result
  OR a.settled_at IS NULL OR r.settled_at IS NULL OR a.settled_at<a.started_at OR r.settled_at<r.started_at OR a.settled_at>a.deadline_at OR r.settled_at>r.deadline_at OR job.sources_read_at<a.settled_at OR job.sources_read_at>r.started_at
  OR a.request_hash IS DISTINCT FROM encode(sha256(convert_to(public.vnext_catalog_canonical_v1(a.frozen_request),'UTF8')),'hex') OR r.request_hash IS DISTINCT FROM encode(sha256(convert_to(public.vnext_catalog_canonical_v1(r.frozen_request),'UTF8')),'hex')
  OR encode(sha256(convert_to(a.frozen_request->>'instructions','UTF8')),'hex') IS DISTINCT FROM '52d58cf0cf9682d8d87a601392589b642009ab8423a38c3acd1aaaff6719f5a5' OR encode(sha256(convert_to(r.frozen_request->>'instructions','UTF8')),'hex') IS DISTINCT FROM '6492f9a20300b9e01e62dc17b184aebfadbd916785c40cc2062dea9c8e02895d' OR a.frozen_request->>'model' IS DISTINCT FROM a.model OR r.frozen_request->>'model' IS DISTINCT FROM r.model THEN RETURN NULL;END IF;
 author_input:=(a.frozen_request->>'input')::jsonb;reviewer_input:=(r.frozen_request->>'input')::jsonb;
 IF author_input IS DISTINCT FROM jsonb_build_object('schemaVersion','vnext-worker-input-v1','task','author','jobId',p_job,'executionId',job.execution_id,'inputHash',p_input_hash,'evidence',jsonb_build_object('cutoff',frozen->'cutoff','evidence',frozen->'evidence'),'symbol',job.symbol,'cancellationContext',context)
  OR reviewer_input IS DISTINCT FROM jsonb_build_object('schemaVersion','vnext-worker-input-v1','task','reviewer','jobId',p_job,'executionId',job.reviewer_execution,'inputHash',p_input_hash,'evidence',jsonb_build_object('cutoff',frozen->'cutoff','evidence',frozen->'evidence'),'symbol',job.symbol,'cancellationContext',context,'authorArtifact',job.author_result) THEN RETURN NULL;END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(job.author_result->'claims') c WHERE c ? 'cancellation')<>1 THEN RETURN NULL;END IF;
 SELECT value INTO claim FROM jsonb_array_elements(job.author_result->'claims') WHERE value ? 'cancellation';annotation:=claim->'cancellation';
 IF claim->>'kind' IS DISTINCT FROM 'assumption' OR claim ? 'numeric' OR claim ? 'semantic' OR jsonb_typeof(annotation) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(annotation))<>8 OR NOT(annotation ?& ARRAY['schemaVersion','symbol','catalystAt','catalystIdentity','baselineRevisionId','baselineClaimId','planned','cancelled']) OR EXISTS(SELECT FROM unnest(ARRAY['schemaVersion','symbol','catalystAt','catalystIdentity']) annotation_field WHERE jsonb_typeof(annotation->annotation_field) IS DISTINCT FROM 'string') OR annotation->>'schemaVersion' IS DISTINCT FROM 'vnext-catalyst-cancellation-v1' OR annotation->>'symbol' IS DISTINCT FROM job.symbol OR jsonb_typeof(annotation->'catalystAt') IS DISTINCT FROM 'string' OR coalesce(annotation->>'catalystAt','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR jsonb_typeof(annotation->'catalystIdentity') IS DISTINCT FROM 'string' THEN RETURN NULL;END IF;
 BEGIN catalyst_day:=(annotation->>'catalystAt')::date;EXCEPTION WHEN datetime_field_overflow OR invalid_datetime_format THEN RETURN NULL;END;
 IF to_char(catalyst_day,'YYYY-MM-DD') IS DISTINCT FROM annotation->>'catalystAt' THEN RETURN NULL;END IF;
 SELECT value INTO planned FROM jsonb_array_elements(frozen->'evidence') WHERE value->>'id'=annotation->'planned'->>'evidenceId';
 SELECT value INTO cancelled FROM jsonb_array_elements(frozen->'evidence') WHERE value->>'id'=annotation->'cancelled'->>'evidenceId';
 IF (SELECT count(*) FROM jsonb_array_elements(frozen->'evidence') e WHERE e->>'id'=annotation->'planned'->>'evidenceId')<>1 OR (SELECT count(*) FROM jsonb_array_elements(frozen->'evidence') e WHERE e->>'id'=annotation->'cancelled'->>'evidenceId')<>1 OR planned IS NULL OR cancelled IS NULL OR planned->>'id'=cancelled->>'id' OR planned->>'contentHash'=cancelled->>'contentHash' OR public.vnext_cancellation_original_v1(planned,annotation->'planned',job.symbol,(frozen->>'cutoff')::timestamptz) IS DISTINCT FROM true OR public.vnext_cancellation_original_v1(cancelled,annotation->'cancelled',job.symbol,(frozen->>'cutoff')::timestamptz) IS DISTINCT FROM true
  OR jsonb_typeof(claim->'evidenceIds') IS DISTINCT FROM 'array' OR jsonb_array_length(claim->'evidenceIds')<>2 OR NOT(claim->'evidenceIds' ? (planned->>'id')) OR NOT(claim->'evidenceIds' ? (cancelled->>'id'))
  OR (planned->'value'->>'publishedAt')::timestamptz>=(cancelled->'value'->>'publishedAt')::timestamptz OR (planned->>'availableAt')::timestamptz>(cancelled->>'availableAt')::timestamptz
  OR catalyst_day<((planned->'value'->>'publishedAt')::timestamptz AT TIME ZONE 'Asia/Taipei')::date OR catalyst_day>((planned->'value'->>'publishedAt')::timestamptz AT TIME ZONE 'Asia/Taipei')::date+interval '3 months' THEN RETURN NULL;END IF;
 identity_text:=annotation->>'catalystIdentity';
 IF char_length(identity_text) NOT BETWEEN 12 AND 160 OR identity_text IS DISTINCT FROM btrim(identity_text) THEN RETURN NULL;END IF;
 FOREACH original_text IN ARRAY ARRAY[planned->'value'->>'statement',cancelled->'value'->>'statement'] LOOP
  IF strpos(original_text,identity_text)=0 OR strpos(substring(original_text FROM strpos(original_text,identity_text)+1),identity_text)>0 THEN RETURN NULL;END IF;
 END LOOP;
 IF strpos(annotation->'planned'->>'quote',identity_text)=0 OR strpos(annotation->'cancelled'->>'quote',identity_text)=0 OR NOT((annotation->'planned'->>'quote') ~ ('(^|[^0-9])'||(annotation->>'catalystAt')||'([^0-9]|$)')) OR NOT((annotation->'cancelled'->>'quote') ~ ('(^|[^0-9])'||(annotation->>'catalystAt')||'([^0-9]|$)')) THEN RETURN NULL;END IF;
 IF context->'baseline'='null'::jsonb THEN
  IF annotation->'baselineRevisionId' IS DISTINCT FROM 'null'::jsonb OR annotation->'baselineClaimId' IS DISTINCT FROM 'null'::jsonb THEN RETURN NULL;END IF;
 ELSE
  IF jsonb_typeof(annotation->'baselineRevisionId') IS DISTINCT FROM 'string' OR annotation->>'baselineRevisionId' IS DISTINCT FROM context->'baseline'->>'revisionId' OR jsonb_typeof(annotation->'baselineClaimId') IS DISTINCT FROM 'string' OR char_length(annotation->>'baselineClaimId') NOT BETWEEN 1 AND 200 THEN RETURN NULL;END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(context->'baseline'->'claims') c WHERE c->>'id'=annotation->>'baselineClaimId')<>1 THEN RETURN NULL;END IF;
  SELECT value INTO baseline_claim FROM jsonb_array_elements(context->'baseline'->'claims') WHERE value->>'id'=annotation->>'baselineClaimId';
  IF baseline_claim->'semantic'->>'outcome' IS DISTINCT FROM 'met' OR coalesce(baseline_claim->'semantic'->>'criterion','') NOT IN('catalyst_dated','catalyst_verified') OR baseline_claim->'semantic'->>'catalystAt' IS DISTINCT FROM annotation->>'catalystAt' OR baseline_claim->'semantic'->>'catalystIdentity' IS DISTINCT FROM identity_text OR baseline_claim->'semantic'->>'evidenceId' IS DISTINCT FROM planned->>'id' OR baseline_claim->'semantic'->>'contentHash' IS DISTINCT FROM planned->>'contentHash' OR (cancelled->'value'->>'publishedAt')::timestamptz<=(context->'baseline'->>'publishedAt')::timestamptz THEN RETURN NULL;END IF;
 END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(job.reviewer_result->'claimChecks') c WHERE c->>'claimId'=claim->>'id')<>1 THEN RETURN NULL;END IF;
 SELECT value INTO checked FROM jsonb_array_elements(job.reviewer_result->'claimChecks') WHERE value->>'claimId'=claim->>'id';assessment:=checked->'cancellationAssessment';
 IF checked->>'verdict' IS DISTINCT FROM 'supported' OR jsonb_typeof(assessment) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(assessment))<>4 OR NOT(assessment ?& ARRAY['schemaVersion','annotation','assessment','reason']) OR assessment->>'schemaVersion' IS DISTINCT FROM 'vnext-catalyst-cancellation-assessment-v1' OR assessment->'annotation' IS DISTINCT FROM annotation OR assessment->>'assessment' IS DISTINCT FROM 'supported_explicit_report' OR jsonb_typeof(assessment->'reason') IS DISTINCT FROM 'string' OR char_length(btrim(assessment->>'reason')) NOT BETWEEN 20 AND 2000 OR char_length(assessment->>'reason')>2000 OR jsonb_typeof(checked->'sources') IS DISTINCT FROM 'array' OR jsonb_array_length(checked->'sources')<>2
  OR NOT EXISTS(SELECT FROM jsonb_array_elements(checked->'sources') s WHERE s->>'id'=planned->>'id' AND s->>'contentHash'=planned->>'contentHash') OR NOT EXISTS(SELECT FROM jsonb_array_elements(checked->'sources') s WHERE s->>'id'=cancelled->>'id' AND s->>'contentHash'=cancelled->>'contentHash') THEN RETURN NULL;END IF;
 proof:=jsonb_build_object('schemaVersion','vnext-catalyst-cancellation-proof-v1','jobId',p_job,'symbol',job.symbol,'inputHash',p_input_hash,'outputHash',job.author_result->>'outputHash','baselineHash',encode(sha256(convert_to(public.vnext_catalog_canonical_v1(context),'UTF8')),'hex'),'annotationHash',encode(sha256(convert_to(public.vnext_catalog_canonical_v1(annotation),'UTF8')),'hex'),'plannedSourceHash',planned->>'contentHash','cancelledSourceHash',cancelled->>'contentHash','authorInvocation',a.invocation_id,'reviewerInvocation',r.invocation_id,'authorExecution',a.execution_id,'reviewerExecution',r.execution_id);
 RETURN proof||jsonb_build_object('proofHash',encode(sha256(convert_to(public.vnext_catalog_canonical_v1(proof),'UTF8')),'hex'));
END;
